// ai-agents/orchestrator/src/activities/noise.ts — sketch, not final code. Activities may use the clock; workflows may not.
import { Gate } from "@rhinohealth/ai-agents-shared";

const IDLE_MS = 7 * 24 * 60 * 60 * 1000;  // 7 days

export async function mayOpenPr(routine: string, repo: string): Promise<Gate> {
  const openPrs = await broker.github.searchPrs(repo, { labels: [`routine:${routine}`], state: "open" });
  if (openPrs.length) {  // one open PR per routine; the run waits, it doesn't open a second one
    return Gate.wait(`${routine} already has #${openPrs[0].number} open`);
  }
  return Gate.go({ labels: [`routine:${routine}`, "agent"], draft: true });  // always a draft first
}

export async function closeIdlePrs(repo: string): Promise<number[]> {
  const closed: number[] = [];
  for (const pr of await broker.github.searchPrs(repo, { labelPrefix: "routine:", state: "open" })) {
    if (Date.now() - pr.lastActivityAt.getTime() < IDLE_MS) continue;  // commits, comments and reviews all count
    await broker.github.comment(pr.number, "Closing: no activity for 7 days. Reopen it to pick it up again.");
    await broker.github.close(pr.number);
    await broker.jira.comment(pr.jiraKey, `Routine PR #${pr.number} was closed after 7 idle days.`);
    closed.push(pr.number);
  }
  return closed;
}

// ai-agents/orchestrator/src/activities/digest.ts — sketch
const WINDOW = 20, MIN_MERGED = 0.5;

export async function mergeRate(routine: string, repo: string): Promise<number | undefined> {
  const closed = await broker.github.searchPrs(repo, { labels: [`routine:${routine}`], state: "closed",
                                                      sort: "closed", limit: WINDOW });
  if (closed.length < WINDOW) {
    return undefined;  // not enough data: never pause on a few PRs
  }
  return closed.filter((pr) => pr.merged).length / WINDOW;
}

export async function autoPause(routine: Routine): Promise<string | undefined> {
  const rate = await mergeRate(routine.name, routine.repo);
  if (rate === undefined || rate >= MIN_MERGED) {
    return undefined;
  }
  const reason = `only ${Math.round(rate * 100)}% of its last ${WINDOW} PRs were merged`;
  await flags.set(`routine:${routine.name}:paused`, reason);  // G3 flag store, checked before every run
  await slack.dm(routine.owner, `${routine.name} is paused: ${reason}.`, { buttons: ["Resume", "Keep paused"] });
  return reason;
}

export async function postTeamDigest(team: string): Promise<void> {
  const items = await collectDigest(team);  // ready PRs, drafts per owner, idle closes, pauses, cost per routine
  if (items.empty) {
    return;  // a quiet day sends nothing
  }
  await slack.post(people.channel(team), renderDigest(team, items));
}

// ai-agents/orchestrator/src/workflows/routine-run.ts — sketch, not final code. Workflow code: deterministic, no Node APIs.
import { proxyActivities, defineSignal, setHandler, sleep, executeChild, workflowInfo } from "@temporalio/workflow";
import type * as activities from "../activities/index.js";
import type { PlanDecision, RoutineRequest, RunOutcome, Trigger } from "@rhinohealth/ai-agents-shared";
import { TaskSpec } from "../routines/task-spec.js";  // pure code, safe to bundle into a workflow
import { shipPr } from "./ship-pr.js";  // the PR half of ticketToPr, shared with Nova
const { loadCharter, preRunGate, saveShadowResult } = proxyActivities<typeof activities>({ startToCloseTimeout: "1 minute" });
const { acquireSandbox } = proxyActivities<typeof activities>({ startToCloseTimeout: "10 minutes" });
const { releaseSandbox } = proxyActivities<typeof activities>({ startToCloseTimeout: "5 minutes" });
const { workInSandbox } = proxyActivities<typeof activities>({  // ticketToPr's activity (G3)
  startToCloseTimeout: "7 days", heartbeatTimeout: "5 minutes" });  // no work-time limit: these only catch a dead worker
export const addTrigger = defineSignal<[Trigger]>("addTrigger");  // target of signal-with-start (G5-09)
export const decidePlan = defineSignal<[PlanDecision]>("decidePlan");  // same Slack buttons as Nova; bug fixers (G5-27)

export async function routineRun(req: RoutineRequest): Promise<string> {
  const triggers: Trigger[] = [];  // every event with the same root cause lands here
  let planDecision: PlanDecision | undefined;  // read by the bug fixers' plan step (G5-27)
  setHandler(addTrigger, (t) => void triggers.push(t));
  setHandler(decidePlan, (d) => { planDecision = d; });
  const charter = await loadCharter(req.routine, req.charterSha);
  if (req.trigger) triggers.push(req.trigger);  // schedules and Jira start without a signal
  if (charter.gather_minutes) await sleep(charter.gather_minutes * 60_000);  // 7 for red main, 0 for bugs (G5-17)
  const gate = await preRunGate(charter, triggers);
  if (gate.verdict !== "go") return park(charter, gate);  // kill switch, paused, incident mode, an open PR: no VM
  const task = TaskSpec.fromCharter(charter, triggers);  // goal, done, skills, paths, model and effort
  const vm = await acquireSandbox({ runId: workflowInfo().runId, agent: req.routine, ...charter.vm });
  let result: RunOutcome;
  try {  // a bigger bug fix returns needs_plan_approval, waits on decidePlan, then resumes in the same VM (G5-27)
    result = await workInSandbox(vm, task);
  } finally {
    await releaseSandbox(vm);
  }
  if (charter.effectiveStage === "shadow") return saveShadowResult(charter, result);  // opens nothing: diff + proof to S3
  return executeChild(shipPr, { args: [{ charter, result }] });
}

// ai-agents/orchestrator/src/triggers/github-events.ts — sketch: POST /v1/events → one routineRun per root cause
import { createHash } from "node:crypto";
import { WorkflowExecutionAlreadyStartedError, WorkflowIdReusePolicy, type Client } from "@temporalio/client";
import { addTrigger, routineRun } from "../workflows/routine-run.js";
const ROUTINES: Record<string, string> = {  // "<workflow name>|<main or renovate>" → routine
  "[FRONTEND] - CI|main": "fe-ci-fixer", "[CLOUD] - CI|main": "be-ci-fixer", "[CLIENT] - CI|main": "be-ci-fixer",
  "[FRONTEND] - CI|renovate": "fe-upgrade-fixer", "[CLOUD] - CI|renovate": "be-upgrade-fixer",
  "[CLIENT] - CI|renovate": "be-upgrade-fixer", "[SDK] - CI|renovate": "be-upgrade-fixer" };

export async function onFailedRun(temporal: Client, ev: WorkflowRunEvent): Promise<string | undefined> {
  const run = await broker.github.getRun(ev.repo, ev.run_id);  // re-read from GitHub; never trust the body
  const kind = run.head_branch === "main" ? "main" : run.head_branch.startsWith("renovate/") ? "renovate" : undefined;
  const routine = kind && ROUTINES[`${run.name}|${kind}`];  // run.name: the workflow's name in GitHub's JSON
  if (!routine || run.conclusion !== "failure") return undefined;
  const workflowId = kind === "renovate"
    ? `upgrade:${ev.repo}:pr-${await broker.github.prForBranch(ev.repo, run.head_branch)}`
    : `cifix:${ev.repo}:${fingerprint(await broker.github.lastGreenSha(ev.repo, run.workflow_id, { branch: "main" }),
                                      await broker.github.failedJobs(ev.repo, run.id))}`;  // name + first error line of each log
  await temporal.workflow.signalWithStart(routineRun, { workflowId, taskQueue: queueFor(routine), args: [{ routine }],
    signal: addTrigger, signalArgs: [Trigger.fromRun(run)],  // joins an open run
    typedSearchAttributes: agentAttribute(routine),  // Agent=cifix|upgrade, as startRun sets it (G3-25)
    workflowIdReusePolicy: WorkflowIdReusePolicy.REJECT_DUPLICATE,  // one run per root cause
  }).catch(async (err: unknown) => {
    if (!(err instanceof WorkflowExecutionAlreadyStartedError)) throw err;
    await alerts.post(`${workflowId} came back after its run closed; a person should look (ping-pong?)`);
  });
  return workflowId;
}

export function fingerprint(baseSha: string, jobs: FailedJob[]): string {
  const parts = jobs.map((j) => `${j.name}|${normalize(j.firstError)}`).sort();
  return createHash("sha256").update([baseSha, ...parts].join("\n")).digest("hex").slice(0, 12);
}
export function normalize(line: string): string {  // drop what changes between runs of the same failure
  return line.toLowerCase().replace(/\b[0-9a-f]{7,40}\b|0x[0-9a-f]+/g, "<hex>").replace(/\d+(\.\d+)?/g, "<n>").slice(0, 200);
}

# ai-agents/evals/routine-bench/collect_red_builds.py — sketch
WORKFLOWS = {"[FRONTEND] - CI": "fe-ci-fixer", "[CLOUD] - CI": "be-ci-fixer", "[CLIENT] - CI": "be-ci-fixer"}


def gh(*args: str) -> str:
    return subprocess.run(["gh", *args, "-R", "RhinoHealth/fcp"], capture_output=True, text=True, check=True).stdout


def red_to_green(workflow: str):
    runs = json.loads(gh("run", "list", "--workflow", workflow, "--branch", "main", "--limit", "400",
                         "--json", "databaseId,conclusion,headSha,createdAt"))
    runs.sort(key=lambda r: r["createdAt"])
    for i, run in enumerate(runs):
        if run["conclusion"] != "failure" or (i and runs[i - 1]["conclusion"] == "failure"):
            continue  # only the first red of each red streak
        green = next((r for r in runs[i + 1:] if r["conclusion"] == "success"), None)
        if green:
            yield run, green


for workflow, routine in WORKFLOWS.items():
    for red, green in red_to_green(workflow):
        case_dir = Path("cases/red-builds") / routine / str(red["databaseId"])
        case_dir.mkdir(parents=True, exist_ok=True)
        log = gh("run", "view", str(red["databaseId"]), "--log-failed")  # empty after ~90 days
        (case_dir / "failed.log").write_text(scrub(log))  # gitleaks + strip tokens before saving
        write_case_yaml(case_dir, routine=routine, workflow=workflow,
                        base_commit=red["headSha"], human_fix=green["headSha"])

// ai-agents/orchestrator/src/triggers/schedules.ts — sketch; G5's part of the file G3-28 creates. Safe to run twice.
import { ScheduleAlreadyRunning, ScheduleOverlapPolicy, type Client, type Workflow } from "@temporalio/client";
import { noiseSweep, routineRun, shadowReport, teamDigest, trustLadder } from "../workflows/index.js";

const BUG_JQL = (label: string) =>
  'project = RH AND issuetype = Bug AND statusCategory = "To Do" AND assignee is EMPTY ' +
  `AND labels = ${label} AND labels not in (no-routine)`; // + Security's customer-data label
// Bug polls use G3-28's registry, like Nova's: one Jira mechanism, one run per ticket (bugfix:RH-1240).
for (const team of ["fe", "be"] as const) {
  QUERIES.set(`bugfix-${team}`, { name: `bugfix-${team}`, agent: "bugfix", every: "5 minutes",
    jql: BUG_JQL(team.toUpperCase()), // the label agreed in G5-07 (proposal: FE / BE)
    toStart: (issue) => [routineRun, { routine: `${team}-bug-fixer`, trigger: { kind: "jira", key: issue.key } }] });
}

const CRON: Record<string, [cron: string, workflow: Workflow, args: unknown[]]> = { // odd minutes; 0-4 = Sun–Thu
  "fe-dead-code": ["17 4 * * 0-4", routineRun, [{ routine: "fe-dead-code" }]],
  "kb-ingest": ["41 6 * * 1", routineRun, [{ routine: "kb-ingest" }]], // G6-20
  "noise-close": ["23 3 * * *", noiseSweep, ["fcp"]],   // G5-02
  "team-digest": ["37 6 * * 0-4", teamDigest, []],      // G5-03
  "trust-ladder": ["51 5 * * *", trustLadder, []],      // G5-15
  "shadow-report": ["13 7 * * 0", shadowReport, []],    // G5-16
};

/** At worker start, next to G3-28's ensureSchedules (the Jira polls). */
export async function ensureCronSchedules(client: Client): Promise<void> {
  for (const [name, [cron, workflowType, args]] of Object.entries(CRON)) {
    const scheduleId = `sched:${name}`;
    const schedule = {
      spec: { cronExpressions: [cron], timezone: "Asia/Jerusalem" },
      action: { type: "startWorkflow" as const, workflowType, args, workflowId: scheduleId, taskQueue: queueFor(name) },
      policies: { overlap: ScheduleOverlapPolicy.SKIP }, // a slow run never stacks a second one
    };
    await client.schedule.create({ scheduleId, ...schedule }).catch(async (err: unknown) => {
      if (!(err instanceof ScheduleAlreadyRunning)) throw err;
      await client.schedule.getHandle(scheduleId).update((previous) => ({ ...previous, ...schedule }));
    });
  }
}

// ai-agents/harness/src/checks/false-heal.ts — sketch; G0's locked-checks detector plus the charter rules
const TEST_FILE = /(^|\/)(tests?|e2e|integration-tests)\/|(^|\/)test_[^/]*\.py$|_test\.py$|\.(test|spec)\.tsx?$/;
const SKIP = /@pytest\.mark\.(skip|xfail)|@unittest\.skip|self\.skipTest\(|\b(it|test|describe)\.(skip|only|fixme)\(/;
const ASSERT = /\bassert\b|self\.assert\w+\(|\bexpect\(/;
const THRESHOLD = /(fail[-_]under|retries|timeout\w*)\s*[:=]\s*([\d.]+)/i;
const RETRY_OR_SLEEP = /time\.sleep\(|asyncio\.sleep\(|@retry|@flaky|--reruns|waitForTimeout\(/;
const count = (rx: RegExp, lines: string[]): number => lines.filter((line) => rx.test(line)).length;

export function falseHeals(diff: FileDiff[], never: Set<string>): string[] {
  const found: string[] = [];
  for (const f of diff) {
    const isTest = TEST_FILE.test(f.path);
    if (f.deleted && isTest) found.push(`${f.path}: test file deleted`);
    found.push(...f.added.filter((line) => SKIP.test(line)).map((line) => `${f.path}: new skip \`${line.trim()}\``));
    if (isTest) {
      const removed = count(ASSERT, f.removed), added = count(ASSERT, f.added);
      if (removed > added) found.push(`${f.path}: ${removed - added} assertion(s) removed`);
      if (never.has("edit_test_assertions") && removed) found.push(`${f.path}: an existing assertion was changed`);
    }
    for (const [key, oldValue, newValue] of pairedChanges(THRESHOLD, f)) {  // the same key on a removed and an added line
      const loosened = key.toLowerCase().includes("fail") ? newValue < oldValue : newValue > oldValue;
      if (loosened) found.push(`${f.path}: ${key} loosened ${oldValue} -> ${newValue}`);
    }
    if (never.has("add_retries_or_sleeps")) {
      found.push(...f.added.filter((line) => RETRY_OR_SLEEP.test(line)).map(() => `${f.path}: retry or sleep added`));
    }
    if (never.has("add_code") && !onlyRemovesTokens(f)) {  // dead-code removers may only delete
      found.push(`${f.path}: new code in a deletions-only routine`);
    }
  }
  return found;  // any finding → outcome false_heal: rejected, and counted on the trust ladder (G5-15)
}

// ai-agents/orchestrator/src/routines/ladder.ts — sketch; a daily schedule calls evaluate() for every routine
const STAGES = ["shadow", "drafts", "normal"] as const;
const pct = (x: number): string => `${Math.round(x * 100)}%`;
export function demotionReason(s: RoutineStats): string | undefined {
  if (s.falseHealsSinceStageChange) return "a false heal";
  if (s.revertedPrsWithin14Days.length) return `#${s.revertedPrsWithin14Days[0]} was reverted within 14 days`;
  if (s.mergeRate !== undefined && s.mergeRate < 0.5) {  // mergeRate() from G5-03, last 20 PRs
    return `only ${pct(s.mergeRate)} of its last 20 PRs merged`;
  }
  return undefined;
}

export function missingForPromotion(s: RoutineStats, bench: SliceScore): string[] {
  const missing: string[] = [];
  if (bench.solvedRate < 0.5) missing.push(`bench slice solved ${pct(bench.solvedRate)}, needs 50%`);
  if (s.kind === "bug-fixer" && bench.reproduceRate < 0.6) {
    missing.push(`reproduced ${pct(bench.reproduceRate)} of bugs, needs 60%`);
  }
  if (s.falseHealsTotal || bench.falseHeals) missing.push("has false heals");
  if (s.runsAtStage < 10) missing.push(`only ${s.runsAtStage} runs at this stage`);  // a starting value; set it from data
  return missing;
}

export async function evaluate(routine: Routine): Promise<void> {
  const [s, bench] = await Promise.all([stats(routine), latestBench(routine)]);  // bench scores from the G1 eval store
  const stage = STAGES.indexOf(routine.effectiveStage);
  const why = demotionReason(s);
  if (why && stage > 0) {
    await flags.set(`routine:${routine.name}:stage_override`, STAGES[stage - 1], { reason: why });  // takes effect now
    await openCharterPr(routine, STAGES[stage - 1], why);  // the file catches up through review
    await slack.dm(routine.owner, `${routine.name} moved back to ${STAGES[stage - 1]}: ${why}`);
  } else if (stage < 2 && missingForPromotion(s, bench).length === 0) {
    await slack.dm(routine.owner, `${routine.name} qualifies for ${STAGES[stage + 1]}. Open the charter PR if you agree.`);
  }
}

// ai-agents/orchestrator/src/reports/shadow-report.ts — sketch; the Sunday schedule calls it
const RUBRIC = `You compare two fixes for the same failure. Answer in JSON with keys
same_root_cause (yes/no/unsure), size (smaller/similar/bigger), reviewer_would_reject (yes/no), why (one line).
Judge the routine's fix on its own merits: a different fix can still be right.`;

export async function weeklyShadowReport(since: Date): Promise<Row[]> {
  const rows: Row[] = [];
  for (const run of await shadowRuns(since)) {  // Stage = 'shadow' AND CloseTime > since
    const human = await findHumanFix(run);  // next green on main, the linked PR, or what the Renovate PR became
    if (!human) {
      rows.push({ run, human: undefined, note: "no human fix yet" });
      continue;
    }
    let tests: TestRun | undefined;
    if (human.addedTests.length) {  // the objective answer: do the human's tests pass on our diff?
      tests = await runOnLiteVm({ base: run.baseSha, patch: run.diffS3Key, tests: human.addedTests });
    }
    const verdict = await judge({ model: "claude-sonnet-5-5", effort: "medium", system: RUBRIC,
                                  inputs: { failure: run.triggerSummary, routine_fix: run.diff, human_fix: human.diff } });
    rows.push({ run, human: human.url, tests, verdict, cost: run.costUsd });
  }
  await postToWeeklyReview(renderTable(rows));  // one thread in the weekly run review, not team channels
  return rows;
}

// ai-agents/orchestrator/src/activities/storm.ts — sketch
const WINDOW_MS = 15 * 60_000, MAX_NEW = 5;  // 15 minutes
const FIXERS = ["fe-ci-fixer", "be-ci-fixer", "pipeline-fixer"];

export async function stormCheck(repo: string): Promise<"normal" | "incident"> {
  const since = new Date(Date.now() - WINDOW_MS).toISOString();
  const names = FIXERS.map((r) => `'${r}'`).join(", ");
  const query = `WorkflowType = 'routineRun' AND RunKind = 'cifix' AND Routine IN (${names}) AND StartTime > '${since}'`;
  const { count: newFingerprints } = await temporal.workflow.count(query);  // one cifix run = one fingerprint (G5-09)
  if (newFingerprints <= MAX_NEW) {
    return "normal";
  }
  const reason = `${newFingerprints} new failure fingerprints in 15 minutes on ${repo}: likely infrastructure, not code`;
  if (await flags.setIfAbsent("routines:fixers:paused", reason)) {  // page once per incident, not per run
    await pagerduty.trigger({ service: "ai-agents", summary: reason });
    await slack.post("#ai-agents-alerts", reason, { details: await firstErrors(query), buttons: ["Resume fixers"] });
  }
  return "incident";
}

export async function stillRed(repo: string, workflowName: string): Promise<boolean> {
  const latest = await broker.github.latestRun(repo, workflowName, { branch: "main" });
  return latest.conclusion === "failure";  // main went green during the gather window → nothing to do
}

// ai-agents/orchestrator/src/activities/storm.ts (continued) — sketch
import type { WorkflowExecutionInfo } from "@temporalio/client";
import { defineSearchAttributeKey, SearchAttributeType } from "@temporalio/common";

const COUNTS_AGAINST = new Set(["failed", "rejected"]);  // handed_off and not_needed are not the routine's fault
const ROUTINE_OUTCOME = defineSearchAttributeKey("RoutineOutcome", SearchAttributeType.KEYWORD);

export async function circuitBreaker(routine: string, owner: string): Promise<boolean> {
  const query = `WorkflowType = 'routineRun' AND Routine = '${routine}' AND ExecutionStatus != 'Running'`;
  const finished: WorkflowExecutionInfo[] = [];
  for await (const w of temporal.workflow.list({ query })) {
    finished.push(w);
    if (finished.length === 20) break;
  }
  const closedAt = (w: WorkflowExecutionInfo): number => w.closeTime?.getTime() ?? 0;
  const last5 = finished.sort((a, b) => closedAt(b) - closedAt(a)).slice(0, 5);
  const bad = last5.filter((w) => COUNTS_AGAINST.has(outcome(w)));
  if (last5.length < 5 || bad.length < 3) {
    return false;
  }
  const reason = `3 of its last 5 runs failed or were rejected: ${bad.map((w) => w.workflowId).join(", ")}`;
  await flags.set(`routine:${routine}:paused`, reason);
  await slack.dm(owner, `${routine} is paused. ${reason}`, { buttons: ["Resume", "Keep paused"] });
  return true;
}

function outcome(w: WorkflowExecutionInfo): string {
  return w.typedSearchAttributes.get(ROUTINE_OUTCOME) ?? "unknown";  // set by routineRun at the end
}

// ai-agents/harness/src/routines/upgrades.ts — sketch: one small pipeline per package (FE and BE upgrade fixers).
// Runs in the harness inside the VM: `vm` is this VM's checkout, commands and agent sessions.
export async function repairGroup(vm: Vm, pr: RenovatePr, charter: Charter): Promise<RepairResult> {
  const breaking: Bump[] = [];
  for (const bump of pr.bumps) {  // 1. each bump alone on the base commit
    await vm.checkout(pr.baseSha);
    await vm.applyBump(bump);  // npm: package.json + lockfile; uv: uv lock --upgrade-package
    if (!(await vm.run(charter.verify_cmd))) breaking.push(bump);  // npm run verify / poe verify (G7)
  }
  const fixCommits: string[] = [];
  for (const bump of breaking) {  // 2. one fix session per breaking package, one writer
    await vm.checkout(pr.baseSha);
    await vm.applyBump(bump);
    const result = await vm.session({ task: "upgrade-dependency", package: bump.package, to: bump.newVersion,
                                      context: [bump.changelogUrl, await vm.usages(bump.package)],
                                      effort: "low", retryEffort: "medium" });
    if (!result.green) {
      return RepairResult.handOff(bump, result.notes);  // a PR comment explains; a person decides
    }
    fixCommits.push(...result.commits);
  }
  await vm.checkout(pr.headSha);  // 3. all fixes together on the real Renovate branch
  await vm.cherryPick(fixCommits);
  if (!(await vm.run([charter.verify_cmd, ...charter.flow_checks]))) {  // flows and stories that use each package
    return RepairResult.handOff(undefined, "the fixes pass one by one but not together");
  }
  return RepairResult.push({ branch: pr.headBranch });  // the broker's git proxy allows this branch only
}

// ai-agents/harness/src/checks/false-heal-workflows.ts — sketch: extra false-heal rules for workflow files
import { parse } from "yaml";

const WEAKENERS: [RegExp, string][] = [
  [/^\s*continue-on-error:\s*true/, "continue-on-error added"],
  [/^\s*if:\s*(false|\$\{\{\s*false\s*\}\})\s*$/, "job or step switched off"],
  [/\|\|\s*(true|exit 0)\s*$/, "failure swallowed with || true"],
  [/-check=false|--no-verify|--exit-code[ =]0/, "check flag turned off"],
];

export function workflowFalseHeals(diff: FileDiff[], requiredChecks: Set<string>): string[] {
  const found: string[] = [];
  for (const f of diff) {
    if (!f.path.startsWith(".github/workflows/")) continue;
    for (const line of f.added) {
      found.push(...WEAKENERS.filter(([rx]) => rx.test(line)).map(([, why]) => `${f.path}: ${why}`));
    }
    const before = jobNames(f.oldText), after = jobNames(f.newText);
    for (const name of before) {  // required checks come from the ruleset (G0)
      if (!after.has(name) && requiredChecks.has(name)) found.push(`${f.path}: removed required check '${name}'`);
    }
    const oldPaths = triggerPaths(f.oldText), newPaths = triggerPaths(f.newText);
    if (newPaths.size < oldPaths.size && [...newPaths].every((p) => oldPaths.has(p))) {
      found.push(`${f.path}: trigger paths narrowed, so the check stops running on some changes`);
    }
  }
  return found;  // merged with falseHeals() (G5-14); any finding rejects the run
}

function jobNames(text: string): Set<string> {  // parsed with the yaml package; a job's check name is name: or its id
  const jobs: Record<string, { name?: string }> = parse(text)?.jobs ?? {};
  return new Set(Object.entries(jobs).map(([id, job]) => job.name ?? id));
}

// ai-agents/harness/src/checks/prove-regression.ts — sketch: the bug fixers' proof before "done" (runs inside the VM)
import { copyFile, mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";

export interface RegressionProof {
  failsWithoutFix: boolean;
  passesWithFix: boolean;
  baseLog: string;
  headLog: string;
}

/** Run the new test twice: on the base commit with only the test files added, then on the fix. */
export async function proveRegressionTest(
  vm: Vm, baseSha: string, testFiles: string[], testCmd: string): Promise<RegressionProof> {
  await vm.exec("git", ["-C", "/work/fcp", "worktree", "add", "/work/base", baseSha]);
  for (const path of testFiles) {  // the test, not the fix
    await mkdir(dirname(join("/work/base", path)), { recursive: true });
    await copyFile(join("/work/fcp", path), join("/work/base", path));
  }
  const base = await vm.exec("bash", ["-c", testCmd], { cwd: "/work/base" });  // must fail
  const head = await vm.exec("bash", ["-c", testCmd], { cwd: "/work/fcp" });   // must pass
  await vm.exec("git", ["-C", "/work/fcp", "worktree", "remove", "--force", "/work/base"]);
  return {
    // An ImportError because the test imports something the fix added is a setup error, not a
    // reproduction: the fixer rewrites the test so it fails on behaviour.
    failsWithoutFix: base.code !== 0 && !base.isSetupError,
    passesWithFix: head.code === 0,
    baseLog: base.tail(80), headLog: head.tail(80),
  };
}

